// Throwaway benchmark: cores (A) sorted Vec, (B) two-level buckets, (C) BTreeMap.
// Each core reproduces the exact stdout of test18.cpp so we get correctness + timing.
use std::fmt::Write as _;
use std::time::Instant;

pub type Key = (i32, i32);

// ---------------------------------------------------------------- CORE A ----
pub mod core_a {
    pub struct SortedMap<K: Ord, V> {
        d: Vec<(K, V)>,
    }
    pub type Cursor = usize;

    impl<K: Ord, V> SortedMap<K, V> {
        pub fn new() -> Self {
            Self { d: Vec::new() }
        }
        pub fn len(&self) -> usize {
            self.d.len()
        }
        pub fn is_empty(&self) -> bool {
            self.d.is_empty()
        }
        pub fn clear(&mut self) {
            self.d.clear()
        }
        pub fn end(&self) -> Cursor {
            self.d.len()
        }
        pub fn lower_bound(&self, k: &K) -> Cursor {
            self.d.partition_point(|e| e.0 < *k)
        }
        pub fn upper_bound(&self, k: &K) -> Cursor {
            self.d.partition_point(|e| e.0 <= *k)
        }
        pub fn equal_range(&self, k: &K) -> (Cursor, Cursor) {
            (self.lower_bound(k), self.upper_bound(k))
        }
        pub fn find(&self, k: &K) -> Cursor {
            let i = self.lower_bound(k);
            if i < self.d.len() && self.d[i].0 == *k {
                i
            } else {
                self.d.len()
            }
        }
        pub fn kv(&self, c: Cursor) -> (&K, &V) {
            let e = &self.d[c];
            (&e.0, &e.1)
        }
        pub fn contains(&self, k: &K) -> bool {
            self.find(k) != self.d.len()
        }
        pub fn insert(&mut self, k: K, v: V) {
            let i = self.lower_bound(&k);
            if i < self.d.len() && self.d[i].0 == k {
                self.d[i].1 = v;
            } else {
                self.d.insert(i, (k, v));
            }
        }
        pub fn erase(&mut self, k: &K) -> bool {
            let i = self.lower_bound(k);
            if i < self.d.len() && self.d[i].0 == *k {
                self.d.remove(i);
                true
            } else {
                false
            }
        }
        pub fn get<'a>(&'a self, k: &K, dflt: &'a V) -> &'a V {
            let c = self.find(k);
            if c == self.d.len() {
                dflt
            } else {
                &self.d[c].1
            }
        }
        pub fn values(&self) -> Vec<V>
        where
            V: Clone,
        {
            self.d.iter().map(|e| e.1.clone()).collect()
        }
        pub fn keys(&self) -> Vec<K>
        where
            K: Clone,
        {
            self.d.iter().map(|e| e.0.clone()).collect()
        }
        pub fn iter(&self) -> impl Iterator<Item = (&K, &V)> {
            self.d.iter().map(|e| (&e.0, &e.1))
        }
    }
    impl<K: Ord, V: Default> SortedMap<K, V> {
        pub fn index_mut(&mut self, k: K) -> &mut V {
            let i = self.lower_bound(&k);
            if i < self.d.len() && self.d[i].0 == k {
                return &mut self.d[i].1;
            }
            self.d.insert(i, (k, V::default()));
            &mut self.d[i].1
        }
    }
}

// ---------------------------------------------------------------- CORE B ----
// Faithful-ish port of Python sortedcontainers: Vec<Vec<(K,V)>>, load factor,
// `maxes` for bucket location, Fenwick tree over bucket lengths for flat rank.
pub mod core_b {
    const LOAD: usize = 1000;

    pub struct SortedMap<K: Ord + Clone, V> {
        lists: Vec<Vec<(K, V)>>,
        maxes: Vec<K>,
        fen: Vec<usize>, // 1-indexed Fenwick over lists[i].len()
        n: usize,
    }
    pub type Cursor = usize; // flat rank; end() == len()

    impl<K: Ord + Clone, V> SortedMap<K, V> {
        pub fn new() -> Self {
            Self { lists: Vec::new(), maxes: Vec::new(), fen: vec![0], n: 0 }
        }
        pub fn len(&self) -> usize {
            self.n
        }
        pub fn is_empty(&self) -> bool {
            self.n == 0
        }
        pub fn clear(&mut self) {
            self.lists.clear();
            self.maxes.clear();
            self.fen = vec![0];
            self.n = 0;
        }
        pub fn end(&self) -> Cursor {
            self.n
        }

        // ---- Fenwick helpers ------------------------------------------------
        fn fen_rebuild(&mut self) {
            let b = self.lists.len();
            self.fen = vec![0usize; b + 1];
            for i in 0..b {
                self.fen[i + 1] = self.lists[i].len();
            }
            for i in 1..=b {
                let j = i + (i & i.wrapping_neg());
                if j <= b {
                    let v = self.fen[i];
                    self.fen[j] += v;
                }
            }
        }
        fn fen_add(&mut self, mut i: usize, delta: isize) {
            let b = self.lists.len();
            i += 1;
            while i <= b {
                self.fen[i] = (self.fen[i] as isize + delta) as usize;
                i += i & i.wrapping_neg();
            }
        }
        /// number of elements in buckets [0, b)
        fn fen_prefix(&self, mut b: usize) -> usize {
            let mut s = 0;
            while b > 0 {
                s += self.fen[b];
                b -= b & b.wrapping_neg();
            }
            s
        }
        /// flat rank -> (bucket, offset)
        fn locate(&self, mut rank: usize) -> (usize, usize) {
            let b = self.lists.len();
            let mut pos = 0usize;
            let mut step = (b + 1).next_power_of_two();
            while step > 0 {
                if pos + step <= b && self.fen[pos + step] <= rank {
                    pos += step;
                    rank -= self.fen[pos];
                }
                step >>= 1;
            }
            (pos, rank)
        }

        // ---- bucket location -------------------------------------------------
        fn bisect_left(&self, k: &K) -> (usize, usize) {
            let bi = self.maxes.partition_point(|m| m < k);
            if bi == self.lists.len() {
                return (bi, 0);
            }
            let off = self.lists[bi].partition_point(|e| e.0 < *k);
            (bi, off)
        }
        fn bisect_right(&self, k: &K) -> (usize, usize) {
            let bi = self.maxes.partition_point(|m| m <= k);
            if bi == self.lists.len() {
                return (bi, 0);
            }
            let off = self.lists[bi].partition_point(|e| e.0 <= *k);
            (bi, off)
        }
        fn flat(&self, bi: usize, off: usize) -> usize {
            if bi >= self.lists.len() {
                return self.n;
            }
            self.fen_prefix(bi) + off
        }

        pub fn lower_bound(&self, k: &K) -> Cursor {
            let (bi, off) = self.bisect_left(k);
            self.flat(bi, off)
        }
        pub fn upper_bound(&self, k: &K) -> Cursor {
            let (bi, off) = self.bisect_right(k);
            self.flat(bi, off)
        }
        pub fn equal_range(&self, k: &K) -> (Cursor, Cursor) {
            (self.lower_bound(k), self.upper_bound(k))
        }
        pub fn find(&self, k: &K) -> Cursor {
            let (bi, off) = self.bisect_left(k);
            if bi < self.lists.len() && off < self.lists[bi].len() && self.lists[bi][off].0 == *k {
                self.flat(bi, off)
            } else {
                self.n
            }
        }
        pub fn kv(&self, c: Cursor) -> (&K, &V) {
            let (b, o) = self.locate(c);
            let e = &self.lists[b][o];
            (&e.0, &e.1)
        }
        pub fn contains(&self, k: &K) -> bool {
            self.find(k) != self.n
        }
        pub fn get<'a>(&'a self, k: &K, dflt: &'a V) -> &'a V {
            let (bi, off) = self.bisect_left(k);
            if bi < self.lists.len() && off < self.lists[bi].len() && self.lists[bi][off].0 == *k {
                &self.lists[bi][off].1
            } else {
                dflt
            }
        }

        fn raw_insert(&mut self, bi: usize, off: usize, k: K, v: V) {
            if self.lists.is_empty() {
                self.lists.push(vec![(k.clone(), v)]);
                self.maxes.push(k);
                self.n = 1;
                self.fen_rebuild();
                return;
            }
            let bi = bi.min(self.lists.len() - 1);
            let off = if bi == self.lists.len() { 0 } else { off.min(self.lists[bi].len()) };
            self.lists[bi].insert(off, (k, v));
            self.n += 1;
            if self.lists[bi].len() > LOAD * 2 {
                let half = self.lists[bi].split_off(LOAD);
                self.maxes[bi] = self.lists[bi].last().unwrap().0.clone();
                let newmax = half.last().unwrap().0.clone();
                self.lists.insert(bi + 1, half);
                self.maxes.insert(bi + 1, newmax);
                self.fen_rebuild();
            } else {
                self.maxes[bi] = self.lists[bi].last().unwrap().0.clone();
                self.fen_add(bi, 1);
            }
        }

        pub fn insert(&mut self, k: K, v: V) {
            let (bi, off) = self.bisect_left(&k);
            if bi < self.lists.len() && off < self.lists[bi].len() && self.lists[bi][off].0 == k {
                self.lists[bi][off].1 = v;
                return;
            }
            // append case: key greater than every max
            if bi == self.lists.len() {
                let last = self.lists.len().saturating_sub(1);
                if self.lists.is_empty() {
                    self.raw_insert(0, 0, k, v);
                } else {
                    let off = self.lists[last].len();
                    self.raw_insert(last, off, k, v);
                }
            } else {
                self.raw_insert(bi, off, k, v);
            }
        }

        pub fn erase(&mut self, k: &K) -> bool {
            let (bi, off) = self.bisect_left(k);
            if bi >= self.lists.len() || off >= self.lists[bi].len() || self.lists[bi][off].0 != *k {
                return false;
            }
            self.lists[bi].remove(off);
            self.n -= 1;
            if self.lists[bi].is_empty() {
                self.lists.remove(bi);
                self.maxes.remove(bi);
                self.fen_rebuild();
            } else {
                self.maxes[bi] = self.lists[bi].last().unwrap().0.clone();
                self.fen_add(bi, -1);
            }
            true
        }

        pub fn keys(&self) -> Vec<K> {
            self.lists.iter().flatten().map(|e| e.0.clone()).collect()
        }
        pub fn values(&self) -> Vec<V>
        where
            V: Clone,
        {
            self.lists.iter().flatten().map(|e| e.1.clone()).collect()
        }
        pub fn iter(&self) -> impl Iterator<Item = (&K, &V)> {
            self.lists.iter().flatten().map(|e| (&e.0, &e.1))
        }
    }
    impl<K: Ord + Clone, V: Default> SortedMap<K, V> {
        pub fn index_mut(&mut self, k: K) -> &mut V {
            let (bi, off) = self.bisect_left(&k);
            let hit = bi < self.lists.len()
                && off < self.lists[bi].len()
                && self.lists[bi][off].0 == k;
            if !hit {
                self.insert(k.clone(), V::default());
            }
            let (bi, off) = self.bisect_left(&k);
            &mut self.lists[bi][off].1
        }
    }
}

// ---------------------------------------------------------------- CORE C ----
// BTreeMap + Option<K> cursors (no stable BTreeCursor on 1.75).
pub mod core_c {
    use std::collections::BTreeMap;
    use std::ops::Bound;

    pub struct SortedMap<K: Ord + Clone, V> {
        m: BTreeMap<K, V>,
    }
    pub type Cursor<K> = Option<K>; // None == end()

    impl<K: Ord + Clone, V> SortedMap<K, V> {
        pub fn new() -> Self {
            Self { m: BTreeMap::new() }
        }
        pub fn len(&self) -> usize {
            self.m.len()
        }
        pub fn is_empty(&self) -> bool {
            self.m.is_empty()
        }
        pub fn clear(&mut self) {
            self.m.clear()
        }
        pub fn end(&self) -> Cursor<K> {
            None
        }
        pub fn lower_bound(&self, k: &K) -> Cursor<K> {
            self.m.range((Bound::Included(k), Bound::Unbounded)).next().map(|(k, _)| k.clone())
        }
        pub fn upper_bound(&self, k: &K) -> Cursor<K> {
            self.m.range((Bound::Excluded(k), Bound::Unbounded)).next().map(|(k, _)| k.clone())
        }
        pub fn equal_range(&self, k: &K) -> (Cursor<K>, Cursor<K>) {
            (self.lower_bound(k), self.upper_bound(k))
        }
        pub fn find(&self, k: &K) -> Cursor<K> {
            if self.m.contains_key(k) {
                Some(k.clone())
            } else {
                None
            }
        }
        pub fn next(&self, c: &Cursor<K>) -> Cursor<K> {
            match c {
                None => None,
                Some(k) => self
                    .m
                    .range((Bound::Excluded(k), Bound::Unbounded))
                    .next()
                    .map(|(k, _)| k.clone()),
            }
        }
        pub fn kv(&self, c: &Cursor<K>) -> (&K, &V) {
            let k = c.as_ref().unwrap();
            self.m.get_key_value(k).unwrap()
        }
        pub fn contains(&self, k: &K) -> bool {
            self.m.contains_key(k)
        }
        pub fn insert(&mut self, k: K, v: V) {
            self.m.insert(k, v);
        }
        pub fn erase(&mut self, k: &K) -> bool {
            self.m.remove(k).is_some()
        }
        pub fn get<'a>(&'a self, k: &K, dflt: &'a V) -> &'a V {
            self.m.get(k).unwrap_or(dflt)
        }
        pub fn keys(&self) -> Vec<K> {
            self.m.keys().cloned().collect()
        }
        pub fn values(&self) -> Vec<V>
        where
            V: Clone,
        {
            self.m.values().cloned().collect()
        }
        pub fn iter(&self) -> impl Iterator<Item = (&K, &V)> {
            self.m.iter()
        }
    }
    impl<K: Ord + Clone, V: Default> SortedMap<K, V> {
        pub fn index_mut(&mut self, k: K) -> &mut V {
            self.m.entry(k).or_default()
        }
    }
}

// ------------------------------------------------------------- DRIVERS ------
macro_rules! driver {
    ($name:ident, $core:path, $cur_deref:tt) => {};
}
let_unused!();

fn main() {}

