// Fuzz core_b (bucket) against BTreeMap oracle: insert/erase/index_mut/find/
// lower_bound/upper_bound/kv(rank)/keys/values/len. Also descending-insert timing.
use std::collections::BTreeMap;
use std::time::Instant;

include!("/tmp/bench/src/cores.rs");

fn lcg2(s: &mut u64) -> u64 {
    *s = s.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
    *s >> 11
}

fn fuzz(seed: u64, ops: usize, keyspace: i32, load_small: bool) -> Result<(), String> {
    let _ = load_small;
    let mut b: core_b::SortedMap<(i32, i32), u32> = core_b::SortedMap::new();
    let mut oracle: BTreeMap<(i32, i32), u32> = BTreeMap::new();
    let mut s = seed;
    for step in 0..ops {
        let op = lcg2(&mut s) % 100;
        let kk = (lcg2(&mut s) as i32).rem_euclid(keyspace);
        let key = (kk, kk * 2);
        let val = (lcg2(&mut s) % 1000) as u32;
        match op {
            0..=54 => {
                b.insert(key, val);
                oracle.insert(key, val);
            }
            55..=79 => {
                let x = b.erase(&key);
                let y = oracle.remove(&key).is_some();
                if x != y {
                    return Err(format!("step {} erase mismatch {:?}", step, key));
                }
            }
            80..=84 => {
                *b.index_mut(key) = val;
                *oracle.entry(key).or_default() = val;
            }
            85..=89 => {
                let got = b.find(&key);
                let want = if oracle.contains_key(&key) {
                    oracle.range(..key).count()
                } else {
                    oracle.len()
                };
                if got != want {
                    return Err(format!("step {} find {:?}: got {} want {}", step, key, got, want));
                }
            }
            90..=94 => {
                let got = b.lower_bound(&key);
                let want = oracle.range(..key).count();
                if got != want {
                    return Err(format!("step {} lb {:?}: got {} want {}", step, key, got, want));
                }
            }
            _ => {
                let got = b.upper_bound(&key);
                let want = oracle.range(..=key).count();
                if got != want {
                    return Err(format!("step {} ub {:?}: got {} want {}", step, key, got, want));
                }
            }
        }
        if b.len() != oracle.len() {
            return Err(format!("step {} len {} vs {}", step, b.len(), oracle.len()));
        }
        // full structural check occasionally (rank -> kv must match ordered oracle)
        if step % 997 == 0 {
            let bk = b.keys();
            let ok: Vec<(i32, i32)> = oracle.keys().cloned().collect();
            if bk != ok {
                return Err(format!("step {} keys diverge", step));
            }
            let bv = b.values();
            let ov: Vec<u32> = oracle.values().cloned().collect();
            if bv != ov {
                return Err(format!("step {} values diverge", step));
            }
            for (i, (k, v)) in oracle.iter().enumerate() {
                let (bk2, bv2) = b.kv(i);
                if bk2 != k || bv2 != v {
                    return Err(format!("step {} kv({}) diverge", step, i));
                }
            }
        }
    }
    Ok(())
}

fn desc_insert_a(n: usize) -> usize {
    let mut m: core_a::SortedMap<(i32, i32), u32> = core_a::SortedMap::new();
    for i in (0..n).rev() {
        m.insert((i as i32, 0), i as u32);
    }
    m.len()
}
fn desc_insert_b(n: usize) -> usize {
    let mut m: core_b::SortedMap<(i32, i32), u32> = core_b::SortedMap::new();
    for i in (0..n).rev() {
        m.insert((i as i32, 0), i as u32);
    }
    m.len()
}
fn desc_insert_c(n: usize) -> usize {
    let mut m: core_c::SortedMap<(i32, i32), u32> = core_c::SortedMap::new();
    for i in (0..n).rev() {
        m.insert((i as i32, 0), i as u32);
    }
    m.len()
}

fn main() {
    let mode = std::env::args().nth(1).unwrap_or_else(|| "fuzz".into());
    if mode == "fuzz" {
        let mut bad = 0;
        // small keyspace -> heavy duplicate/erase churn; large -> many splits
        for (ks, ops) in [(50i32, 20_000usize), (500, 60_000), (5_000, 200_000), (60_000, 400_000)] {
            for seed in 1..=8u64 {
                match fuzz(seed * 7919, ops, ks, false) {
                    Ok(()) => {}
                    Err(e) => {
                        println!("FAIL ks={} seed={} : {}", ks, seed, e);
                        bad += 1;
                    }
                }
            }
            println!("fuzz keyspace={:>6} ops={:>7} x8 seeds : {}", ks, ops, if bad == 0 { "all pass" } else { "FAILURES" });
        }
        println!("total failures = {}", bad);
    } else {
        for &n in &[200_000usize, 1_000_000] {
            let t = Instant::now();
            let r = desc_insert_a(n);
            println!("descending-insert n={:>8} A vec     {:>9.1} ms (len {})", n, t.elapsed().as_secs_f64() * 1e3, r);
            let t = Instant::now();
            let r = desc_insert_b(n);
            println!("descending-insert n={:>8} B bucket  {:>9.1} ms (len {})", n, t.elapsed().as_secs_f64() * 1e3, r);
            let t = Instant::now();
            let r = desc_insert_c(n);
            println!("descending-insert n={:>8} C btree   {:>9.1} ms (len {})", n, t.elapsed().as_secs_f64() * 1e3, r);
        }
    }
}

